// UI capture for T3j. Do not edit this file after it has run.
// Title strings are the firmware DrawText strings. A tab page's title is the
// page-number token joined to the section name. A subpage's title is the header
// string. A chooser's highlighted slot is the face image id, or the stock slot
// text when the face is a string. Those string ids are the two stock priority
// faces from T3h (0x124f and 0x127b).

export const SECTIONS = new Set([
  'Card/Folder/File', 'Grid/Other Displays', 'Information', 'Live View', 'Operations',
  'Displays', 'File', 'Shooting Assist', 'Sound Recording/Connection', 'Image Stabilizer',
  'ISO/Noise Reduction', 'Picture Mode/WB', 'Basic Settings/Image Quality', 'MF',
  'AF Target Settings & Operations', 'Movie AF', 'AF',
]);

const HELP_2154 = 'When a specified subject is detected at\r\nthe selected AF target position, AF is\r\nperformed on the detected subject.';

export const HEADERS = [
  '@A02C@@A065@AF Button',
  'Release Priority',
  '@A02C@AF by half-pressing @A052@',
  'AF Target Mode',
  'Choose the AF target area.',
  HELP_2154,
];

// Kind-4 slot string ids. 0x124f and 0x127b, T3h faces.md.
export const STRING_FACE = {
  4687: '@A02F@ Priority',
  4731: '@A066@ Priority',
};

export function pageTitle(texts) {
  if (!texts || !texts.length) return null;
  const num = texts.find((t) => /^\d+\.$/.test(t));
  const section = texts.find((t) => SECTIONS.has(t));
  if (num && section) return num + section;
  for (const header of HEADERS) {
    if (texts.includes(header)) return header;
  }
  return texts[0];
}

export function invariantSnapshot(cells) {
  return {
    k90a1: cells.k90a1,
    k1dd1: cells.k1dd1,
    k99a1: cells.k99a1,
    k9a41: cells.k9a41,
    k5962: cells.k5962,
    home: cells.home,
    originally: cells.originally.map((x) => x.value),
  };
}

export function capture(ctx, id) {
  const view = ctx.shot(id);
  const faces = ctx.takeFaces();
  const cells = ctx.cells();
  const help = [...faces].reverse().find((f) => f.caller === '0x611f843e') || null;
  const glyphFace = [...faces].reverse().find((f) => f.caller === '0x6120408f' && f.list === '0x6158ba1c') || null;
  let highlight = view.highlight;
  let slot = null;
  if (highlight == null && help) {
    slot = [...faces].reverse().find((f) => f.caller === '0x611f83b1' && f.value === help.value) || null;
    if (slot && slot.id != null && slot.kind === 12) highlight = slot.id;
    else if (slot && slot.id != null && slot.kind === 4) highlight = STRING_FACE[slot.id] ?? slot.id;
  }
  const file = view.file ? view.file.split(/[/\\]/).pop() : null;
  return {
    title: pageTitle(view.texts),
    highlight,
    texts: view.texts,
    screenshot: file,
    screen: ctx.s.screen(),
    profile: cells.profile,
    profileCached: cells.profileCached,
    helpId: help ? help.id : null,
    slotValue: help ? help.value : null,
    slotKind: slot ? slot.kind : null,
    slotId: slot ? slot.id : null,
    glyph: glyphFace && glyphFace.id != null ? { value: glyphFace.value, id: glyphFace.id } : null,
    cells,
    invariant: invariantSnapshot(cells),
    error: view.error || null,
  };
}

function keyStep(id, key, shared) {
  return { id, key, shared, lane: 'main' };
}

export function mainSteps(candidate) {
  const steps = [
    { id: 'baseline', action: 'baseline', shared: true, lane: 'main' },
    keyStep('menu', 'menu', true),
  ];
  for (let i = 0; i < 20; i++) steps.push(keyStep('left-' + i, 'left', true));
  steps.push(
    keyStep('down-caf', 'down', true),
    keyStep('down-afbutton', 'down', true),
    keyStep('page27', 'ok', true),
    keyStep('2154-open', 'ok', true),
    keyStep('2154-cancel', 'menu', true),
    keyStep('down-2155', 'down', true),
    keyStep('2155-open', 'ok', true),
    keyStep('2155-cancel', 'menu', true),
    keyStep('leave-27', 'menu', true),
    keyStep('page1-af', 'left', true),
    keyStep('down26-0', 'down', true),
    keyStep('down26-1', 'down', true),
    keyStep('down26-2', 'down', true),
    keyStep('down26-3', 'down', true),
    keyStep('down26-4', 'down', true),
    keyStep('page26', 'ok', true),
    keyStep('back26', 'menu', true),
    keyStep('up25-0', 'up', true),
    keyStep('up25-1', 'up', true),
    keyStep('page25', 'ok', true),
    keyStep('back25', 'menu', true),
    keyStep('page2-af', 'right', true),
    keyStep('down27-0', 'down', true),
    keyStep('down27-1', 'down', true),
    keyStep('page27-return', 'ok', true),
  );
  if (candidate) {
    steps.push(
      keyStep('zone-2155', 'down', false),
      keyStep('zone-row', 'down', false),
      keyStep('zone-open', 'ok', false),
    );
    for (let n = 1; n <= 9; n++) steps.push(keyStep('zone-right-' + n, 'right', false));
    steps.push(
      keyStep('zone-cancel-c4', 'menu', false),
      keyStep('zone-reopen', 'ok', false),
      keyStep('commit2-right-1', 'right', false),
      keyStep('commit2-right-2', 'right', false),
      keyStep('commit-2', 'ok', false),
      keyStep('reopen-2', 'ok', false),
    );
    for (let n = 3; n <= 9; n++) steps.push(keyStep('commit9-right-' + n, 'right', false));
    steps.push(keyStep('commit-9', 'ok', false));
  }
  steps.push(
    keyStep('exit-0', 'menu', true),
    keyStep('exit-1', 'menu', true),
    { id: 'save', action: 'save', shared: true, lane: 'main' },
  );
  return steps;
}

export function page28Steps() {
  const steps = [
    { id: 'p28-arm', action: 'reference-construction', shared: true, lane: 'page28' },
    { id: 'p28-menu', key: 'menu', shared: true, lane: 'page28' },
  ];
  for (let i = 0; i < 20; i++) steps.push({ id: 'p28-left-' + i, key: 'left', shared: true, lane: 'page28' });
  steps.push(
    { id: 'p28-down-0', key: 'down', shared: true, lane: 'page28' },
    { id: 'p28-down-1', key: 'down', shared: true, lane: 'page28' },
    { id: 'p28-open', key: 'ok', shared: true, lane: 'page28' },
  );
  return steps;
}

export async function applyStep(ctx, step) {
  if (step.action === 'baseline') return capture(ctx, step.id);
  if (step.action === 'reference-construction') {
    ctx.page28State.phase = 'build';
    ctx.emit('behaviour', {
      step: step.id,
      label: 'EMULATOR-ONLY reference construction. Page-28 build phase armed before the key path. Not a native route. Role: behaviour.',
    });
    return capture(ctx, step.id);
  }
  if (step.action === 'save') {
    ctx.idle(800);
    const row = capture(ctx, step.id);
    const saves = ctx.l.store_log?.nvram?.saves ?? [];
    row.saves = saves.length;
    row.saveNames = saves.map((s) => s.store);
    return row;
  }
  if (step.key) {
    ctx.press(step.key);
    return capture(ctx, step.id);
  }
  throw new Error('step has neither key nor action: ' + step.id);
}
